,
      searchForm: {
        recipient: '',
        receiverName: '',
        phone: '',
        address: ''
      },
      searchParams: {}

handleSearch() {
  this.searchParams = { ...this.searchForm }
  this.getList()
},
handleReset() {
  this.searchForm = {
    recipient: '',
    receiverName: '',
    phone: '',
    address: ''
  }
  this.searchParams = {}
  this.getList()
},

handleButtonClick(code) {
  if (code === 'reset') {
    this.$refs['dataListView'].reset()
  } else if (code === 'query') {
    this.getList()
  }
},
